import assert from 'node:assert/strict';
import { after, before, describe, it } from 'node:test';
import { api, startTestServer, type TestServer } from './helpers.ts';

const CARRIERS = ['ATP', 'DHL', 'DPD', 'GLS', 'UPS'] as const;

describe('GET /shipments on a large dataset (5k)', () => {
  let srv: TestServer;

  before(async () => {
    srv = await startTestServer();
    const base = Date.now();
    for (let i = 0; i < 5000; i++) {
      const s = srv.store.addShipment(
        {
          trackingNumber: `BULK${i}`,
          carrier: CARRIERS[i % CARRIERS.length],
          serviceLevel: 'standard',
          recipient: { name: 'Test', address: 'Teststraße 1, 1010 Wien', phone: '+43 1 0000000' },
        },
        new Date(base - i * 60_000),
      );
      srv.store.addEvent(s.id, 'picked_up');
      if (i % 3 === 0) srv.store.addEvent(s.id, 'exception');
    }
  });

  after(async () => {
    await srv.close();
  });

  it('answers a limit=500 list fast, newest first, with correct fresh etas (no caching)', async () => {
    await api(srv.url, 'GET', '/shipments?limit=500'); // warm-up
    const t0 = performance.now();
    const res = await api(srv.url, 'GET', '/shipments?limit=500');
    const ms = performance.now() - t0;

    assert.equal(res.status, 200);
    assert.equal(res.body.count, 500);
    // generous budget (typical: ~20 ms) so slow CI machines don't flake, but O(n^2) regressions fail
    assert.ok(ms < 500, `list took ${ms.toFixed(0)} ms`);

    const created = res.body.items.map((i: { created_at: string }) => i.created_at);
    assert.deepEqual(created, [...created].sort().reverse());

    for (const item of [res.body.items[0], res.body.items[250], res.body.items[499]]) {
      const single = await api(srv.url, 'GET', `/shipments/${item.id}`);
      assert.equal(item.eta, single.body.eta);
    }
  });
});
EOF
